  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);
const KNOWN_SECRETS = ['TRANSCRIPTION_API_KEY', 'TRANSCRIPTION_WEBHOOK_SECRET', 'OPENAI_API_KEY', 'HUBSPOT_ACCESS_TOKEN', 'SLACK_WEBHOOK_URL']
  .map((k) => env(k, '')).filter((v) => v.length >= 8);
const SECRET_KEY = /(authorization|token|secret|password|passwd|api[-_]?key|cookie|signature|webhook[-_]?url)/i;
const redactString = (input) => {
  let s = String(input ?? '');
  for (const secret of KNOWN_SECRETS) s = s.split(secret).join('[REDACTED]');
  return s
    .replace(/\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{4,}/g, '[REDACTED_JWT]')
    .replace(/Basic\s+[A-Za-z0-9+\/]{8,}=*/gi, 'Basic [REDACTED]')
    .replace(/Bearer\s+[A-Za-z0-9\-._~+\/]+=*/gi, 'Bearer [REDACTED]')
    .replace(/\bsk-[A-Za-z0-9_\-]{16,}/g, '[REDACTED_OPENAI_KEY]')
    .replace(/\bpat-[a-z0-9]{2,6}-[A-Za-z0-9-]{8,}\b/gi, '[REDACTED_HUBSPOT_TOKEN]')
    .replace(/-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g, '[REDACTED_PRIVATE_KEY]')
    .replace(/https:\/\/hooks\.slack\.com\/[^\s"']+/gi, '[REDACTED_SLACK_WEBHOOK]')
    .replace(/([?&](?:api_key|apikey|key|token|secret|signature|sig)=)[^&\s"']+/gi, '$1[REDACTED]')
    .replace(/\b([A-Za-z0-9._%+-])[A-Za-z0-9._%+-]*@([A-Za-z0-9.-]+\.[A-Za-z]{2,})\b/g, '$1***@$2')
