  return {
    json: {
      ...alert,
      notify,
      slackMessage: {
        text: `Sales pitch compliance audit failed at ${alert.lastNodeExecuted || 'unknown node'}`,
        blocks: [
          { type: 'header', text: { type: 'plain_text', text: '⚠️ Sales pitch compliance audit failed', emoji: true } },
          { type: 'section', text: { type: 'mrkdwn', text: `*Node:* ${alert.lastNodeExecuted || 'unknown'}\n*Error:* ${alert.errorName}: ${alert.errorMessage}` } },
